SELECT i.inquiry_id, i.product_id, i.title, i.content, i.is_secret, i.is_answered, i.created_at, u.username FROM inquiry i LEFT JOIN users u ON u.user_id = i.created_by
AND product_id = #{productId}
AND is_answered = #{isAnswered}
AND i.upper_inquiry_id is null
ORDER BY created_at DESC LIMIT #{size} OFFSET #{offset}

